39	import org.springframework.samples.petclinic.rest.assignment.HouseholdIdGenerator;
40	import org.springframework.samples.petclinic.rest.assignment.HouseholdSizeCalculator;
41	import org.springframework.samples.petclinic.rest.audit.OwnerAuditLogger;
42	import org.springframework.samples.petclinic.rest.signup.BulkSignupWarningEvaluator;
