16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.Period;
26	import java.time.temporal.ChronoUnit;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "postcode")
57	    private String postcode;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "birth_date")
63	    private LocalDate birthDate;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "household_size")
75	    private Integer householdSize;
76	
77	    @Column(name = "possible_duplicate")
78	    private Boolean possibleDuplicate;
79	
80	    @Column(name = "possible_duplicate_of")
81	    private Integer possibleDuplicateOf;
82	
83	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
84	    private Set<Pet> pets;
85	
86	    public String getAddress() {
87	        return this.address;
88	    }
89	
90	    public void setAddress(String address) {
91	        this.address = address;
92	    }
93	
94	    public String getCity() {
95	        return this.city;
96	    }
97	
98	    public void setCity(String city) {
99	        this.city = city;
100	    }
101	
102	    public String getTelephone() {
103	        return this.telephone;
104	    }
105	
106	    public void setTelephone(String telephone) {
107	        this.telephone = telephone;
108	    }
109	
110	    /**
111	     * The owner's stored E.164 {@link #getTelephone() telephone} formatted for humans: the country
112	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}).
113	     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
114	     * been set.
115	     */
116	    public String getTelephoneDisplay() {
117	        return Telephone.forDisplay(this.telephone);
118	    }
119	
120	    public String getEmail() {
121	        return this.email;
122	    }
123	
124	    public void setEmail(String email) {
125	        this.email = email;
126	    }
127	
128	    public String getPostcode() {
129	        return this.postcode;
130	    }
131	
132	    public void setPostcode(String postcode) {
133	        this.postcode = postcode;
134	    }
135	
136	    public LocalDate getRegistrationDate() {
137	        return this.registrationDate;
138	    }
139	
140	    public void setRegistrationDate(LocalDate registrationDate) {
141	        this.registrationDate = registrationDate;
142	    }
143	
144	    public LocalDate getBirthDate() {
145	        return this.birthDate;
146	    }
147	
148	    public void setBirthDate(LocalDate birthDate) {
149	        this.birthDate = birthDate;
150	    }
151	
152	    public String getCustomerCode() {
153	        return this.customerCode;
154	    }
155	
156	    public void setCustomerCode(String customerCode) {
157	        this.customerCode = customerCode;
158	    }
159	
160	    public String getHouseholdId() {
161	        return this.householdId;
162	    }
163	
164	    public void setHouseholdId(String householdId) {
165	        this.householdId = householdId;
166	    }
167	
168	    public Integer getNamesakeCount() {
169	        return this.namesakeCount;
170	    }
171	
172	    public void setNamesakeCount(Integer namesakeCount) {
173	        this.namesakeCount = namesakeCount;
174	    }
175	
176	    public Integer getHouseholdSize() {
177	        return this.householdSize;
178	    }
179	
180	    public void setHouseholdSize(Integer householdSize) {
181	        this.householdSize = householdSize;
182	    }
183	
184	    /**
185	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
186	     * postcode while holding a different telephone. Resolved at creation and stored so it is
187	     * reported consistently on every later read.
188	     */
189	    public Boolean getPossibleDuplicate() {
190	        return this.possibleDuplicate;
191	    }
192	
193	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
194	        this.possibleDuplicate = possibleDuplicate;
195	    }
196	
197	    /**
198	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
199	     * is not a possible duplicate.
200	     */
201	    public Integer getPossibleDuplicateOf() {
202	        return this.possibleDuplicateOf;
203	    }
204	
205	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
206	        this.possibleDuplicateOf = possibleDuplicateOf;
207	    }
208	
209	    /**
210	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
211	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
212	     * email or household contributes an empty string. Two owners are duplicates only when their
213	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
214	     * different telephones have distinct identity keys and are both allowed.
215	     */
216	    public String getIdentityKey() {
217	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
218	    }
219	
220	    private static String orEmpty(String value) {
221	        return value == null ? "" : value;
222	    }
223	
224	    /**
225	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
226	     * last two digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}). Derived
227	     * from the owner's own fields; absent until both the customer code and registration date
228	     * have been assigned.
229	     */
230	    public String getMembershipNumber() {
231	        if (this.customerCode == null || this.registrationDate == null) {
232	            return null;
233	        }
234	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
235	    }
236	
237	    /**
238	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
239	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
240	     */
241	    public Integer getCheckDigit() {
242	        if (this.customerCode == null) {
243	            return null;
244	        }
245	        return Luhn.checkDigit(this.customerCode);
246	    }
247	
248	    /**
249	     * The owner's tenure in whole days: the number of days elapsed from the
250	     * {@link #getRegistrationDate() registration date} up to today. A freshly registered owner has
251	     * a tenure of zero. Absent until a registration date is present.
252	     */
253	    public Long getTenureDays() {
254	        if (this.registrationDate == null) {
255	            return null;
256	        }
257	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
258	    }
259	
260	    /**
261	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
262	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
263	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
264	     * points once the owner's {@link #getTenureDays() tenure} exceeds 365 days.
265	     */
266	    public Integer getMembershipPoints() {
267	        int points = 0;
268	        boolean hasEmail = this.email != null && !this.email.isEmpty();
269	        if (hasEmail) {
270	            points += 2;
271	        }
272	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
273	        if (unique) {
274	            points += 1;
275	        }
276	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
277	        if (sharedHousehold) {
278	            points += 2;
