19	import java.util.Locale;
20	import java.util.Map;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Normalizes a submitted street address into a single canonical form: whitespace is trimmed and
26	 * collapsed, the text is upper-cased, and common street-type abbreviations are expanded
27	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Applying this once when an
28	 * owner is created means every consumer - the required-field check, duplicate detection, the shared
29	 * household id, and the stored value - sees the same normalized address.
30	 */
31	@Component
32	public class AddressNormalizer {
33	
34	    /** Whole-word abbreviations expanded to their canonical, upper-case form. */
35	    private static final Map<String, String> ABBREVIATIONS = Map.of(
36	        "ST", "STREET",
37	        "RD", "ROAD",
38	        "AVE", "AVENUE");
39	
40	    /**
41	     * @param address the raw, possibly formatted street address (may be {@code null})
42	     * @return the trimmed, whitespace-collapsed, upper-cased address with abbreviations expanded;
43	     * an empty string when no meaningful text was supplied
44	     */
45	    public String normalize(String address) {
46	        if (address == null) {
47	            return "";
48	        }
49	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
50	        if (collapsed.isEmpty()) {
51	            return "";
52	        }
53	        String[] words = collapsed.split(" ");
54	        StringBuilder result = new StringBuilder(collapsed.length());
55	        for (int i = 0; i < words.length; i++) {
56	            if (i > 0) {
57	                result.append(' ');
58	            }
59	            result.append(ABBREVIATIONS.getOrDefault(words[i], words[i]));
60	        }
61	        return result.toString();
62	    }
63	}
