21	import org.springframework.samples.petclinic.model.Regions;
22	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
23	import org.springframework.samples.petclinic.rest.error.InvalidPostcodeException;
24	import org.springframework.stereotype.Component;
25	import org.springframework.util.StringUtils;
26	
27	/**
28	 * Validates an owner's optional postcode. When present it must be a 4-digit code and, if the
29	 * owner's city maps to a known region, must fall within that region's inclusive postcode range.
30	 * A city with no known region accepts any 4-digit postcode. An absent postcode is always accepted.
31	 */
32	@Component
33	public class PostcodeValidator {
34	
35	    private static final Pattern FOUR_DIGITS = Pattern.compile("\\d{4}");
36	
37	    /**
38	     * @param owner the submitted owner fields
39	     * @throws InvalidPostcodeException if a postcode is present but is not 4 digits or is out of
40	     * range for the region of the owner's city
41	     */
42	    public void validate(OwnerFieldsDto owner) {
43	        String postcode = owner.getPostcode();
44	        if (!StringUtils.hasText(postcode)) {
45	            return;
46	        }
47	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
48	            throw new InvalidPostcodeException(postcode);
49	        }
50	        int[] range = Regions.rangeOf(Regions.regionOfCity(owner.getCity()));
51	        if (range != null) {
52	            int value = Integer.parseInt(postcode);
53	            if (value < range[0] || value > range[1]) {
54	                throw new InvalidPostcodeException(postcode);
55	            }
56	        }
57	    }
58	}
