17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.rest.error.DuplicateOwnerException;
21	import org.springframework.samples.petclinic.service.ClinicService;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Rejects creating an owner that duplicates an existing household. The household is keyed on (last
26	 * name, postcode) through the {@link HouseholdKey}, so a new owner is a duplicate whenever an
27	 * existing owner already belongs to the same household. The caller bypasses this check when the
28	 * create deliberately declares a shared household.
29	 */
30	@Component
31	public class DuplicateOwnerValidator {
32	
33	    private final ClinicService clinicService;
34	
35	    private final HouseholdKey householdKey;
36	
37	    public DuplicateOwnerValidator(ClinicService clinicService, HouseholdKey householdKey) {
38	        this.clinicService = clinicService;
39	        this.householdKey = householdKey;
40	    }
41	
42	    /**
43	     * @param owner the owner being created, with its telephone, email and household id already
44	     * resolved so its {@link Owner#getIdentityKey() identityKey} is final
45	     * @throws DuplicateOwnerException if another owner already belongs to the same household
46	     */
47	    public void validate(Owner owner) {
48	        String key = this.householdKey.of(owner.getLastName(), owner.getPostcode());
49	        boolean duplicate = this.clinicService.findAllOwners().stream()
50	            .anyMatch(existing -> key.equals(
51	                this.householdKey.of(existing.getLastName(), existing.getPostcode())));
52	        if (duplicate) {
53	            throw new DuplicateOwnerException(owner.getIdentityKey());
54	        }
55	    }
56	}
