23	/**
24	 * Derives an owner's {@code householdId}: a stable identifier shared by every owner in the same
25	 * household. Because it is a pure function of the {@link HouseholdKey} over (last name, postcode),
26	 * owners with the same last name and postcode always yield the same value: the first 12 hex
27	 * characters of the SHA-256 of that key.
28	 */
29	@Component
30	public class HouseholdIdGenerator {
31	
32	    private final HouseholdKey householdKey;
33	
34	    public HouseholdIdGenerator(HouseholdKey householdKey) {
35	        this.householdKey = householdKey;
36	    }
37	
38	    /**
39	     * @param lastName the owner's last name
40	     * @param postcode the owner's postcode
41	     * @return the stable household identifier for that last name and postcode
42	     */
43	    public String generate(String lastName, String postcode) {
44	        String key = this.householdKey.of(lastName, postcode);
45	        return Sha256.hex(key).substring(0, 12);
46	    }
47	}
