18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.rest.validation.HouseholdKey;
21	import org.springframework.samples.petclinic.service.ClinicService;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Computes the size of an owner's household. Because the household is keyed on (last name, postcode)
26	 * every owner already carries the shared {@code householdId}, so there is nothing to link: the size
27	 * is simply the joining owner plus every existing owner in the same {@link HouseholdKey household}.
28	 */
29	@Component
30	public class HouseholdSizeCalculator {
31	
32	    private final ClinicService clinicService;
33	
34	    private final HouseholdKey householdKey;
35	
36	    public HouseholdSizeCalculator(ClinicService clinicService, HouseholdKey householdKey) {
37	        this.clinicService = clinicService;
38	        this.householdKey = householdKey;
39	    }
40	
41	    /**
42	     * @param owner the owner being created, not yet saved
43	     * @return the number of members in the household once {@code owner} joins, counting the joining
44	     * owner and every existing owner with the same last name and postcode
45	     */
46	    public int size(Owner owner) {
47	        String key = this.householdKey.of(owner.getLastName(), owner.getPostcode());
48	        int members = 1;
49	        for (Owner existing : this.clinicService.findAllOwners()) {
50	            if (this.householdKey.of(existing.getLastName(), existing.getPostcode()).equals(key)) {
51	                members++;
52	            }
53	        }
54	        return members;
55	    }
56	}
