35	
36	/**
37	 * JPA implementation of the {@link OwnerRepository} interface.
38	 *
39	 * @author Mike Keith
40	 * @author Rod Johnson
41	 * @author Sam Brannen
42	 * @author Michael Isvy
43	 * @author Vitaliy Fedoriv
44	 */
45	@Repository
46	@Profile("jpa")
47	public class JpaOwnerRepositoryImpl implements OwnerRepository {
48	
49	    @PersistenceContext
50	    private EntityManager em;
51	
52	
53	    /**
54	     * Important: in the current version of this method, we load Owners with all their Pets and Visits while
55	     * we do not need Visits at all and we only need one property from the Pet objects (the 'name' property).
56	     * There are some ways to improve it such as:
57	     * - creating a Ligtweight class (example here: https://community.jboss.org/wiki/LightweightClass)
58	     * - Turning on lazy-loading and using open session in view pattern
59	     */
60	    @SuppressWarnings("unchecked")
61	    public Collection<Owner> findByLastName(String lastName) {
62	        // using 'join fetch' because a single query should load both owners and pets
63	        // using 'left join fetch' because it might happen that an owner does not have pets yet
64	        Query query = this.em.createQuery("SELECT DISTINCT owner FROM Owner owner left join fetch owner.pets WHERE owner.lastName LIKE :lastName");
65	        query.setParameter("lastName", lastName + "%");
66	        return query.getResultList();
67	    }
68	
69	    @Override
70	    @SuppressWarnings("unchecked")
71	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
72	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.lastName LIKE :lastName ORDER BY owner.id");
73	        query.setParameter("lastName", lastName + "%");
74	        query.setFirstResult((int) pageable.getOffset());
75	        query.setMaxResults(pageable.getPageSize());
76	        List<Owner> owners = query.getResultList();
77	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.lastName LIKE :lastName");
78	        countQuery.setParameter("lastName", lastName + "%");
79	        long total = (long) countQuery.getSingleResult();
80	        return new PageImpl<>(owners, pageable, total);
81	    }
82	
83	    @Override
84	    @SuppressWarnings("unchecked")
85	    public Collection<Owner> findByTelephone(String telephone) throws DataAccessException {
86	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.telephone = :telephone");
87	        query.setParameter("telephone", telephone);
